154		// No usable selection (nothing discovered, discovery refused, or the operator unchecked
155		// "all points" without picking any): /api/intruder/run would refuse the launch, so say so
156		// on the confirm step instead of minting a token for a call that cannot succeed.
157		if selErr != "" {
158			model := map[string]any{
159				"error": selErr,
160				"run":   run, "form": r.PostForm,
161			}
162			w.Header().Set("Content-Type", "text/html; charset=utf-8")
163			_, _ = w.Write([]byte(ui2Exec("intruder_confirm.html", model)))
164			return
165		}
166		payload, _ := ui2Marshal(run)
167		token, preview, errText := s.ui2MintConfirm("/api/intruder/run", http.MethodPost, "/api/intruder/run", payload)
168		model := map[string]any{
169			"token": token, "preview": preview, "error": errText,
170			"run": run, "form": r.PostForm,
171		}
172		w.Header().Set("Content-Type", "text/html; charset=utf-8")
173		_, _ = w.Write([]byte(ui2Exec("intruder_confirm.html", model)))
174	}
