176	// handleUI2IntruderRun serves POST /ui2/intruder/run: spends the token on the real call.
177	func (s *Server) handleUI2IntruderRun(w http.ResponseWriter, r *http.Request) {
178		_ = r.ParseForm()
179		token := r.PostFormValue("token")
180		run, selErr := s.ui2IntruderRunPayload(r)
181		attacks, _ := s.ui2APIResult(http.MethodGet, "/api/intruder/attacks", nil)
182		wordlists, _ := s.ui2APIResult(http.MethodGet, "/api/wordlists", nil)
183		model := map[string]any{"attacks": attacks, "wordlists": wordlists}
184		if selErr != "" {
185			// No dispatch at all without a real selection — spending the confirmation on a body
186			// the operator never reviewed is the failure this branch exists to prevent.
187			model["error"] = selErr
188		} else {
189			result, errText := s.ui2DispatchConfirmed(http.MethodPost, "/api/intruder/run", run, token)
190			model["result"] = result
191			model["error"] = errText
192			// /api/intruder/run answers when the attack is over, and its registry entry is gone by
193			// then — without this link the just-finished attack's results are unreachable from here.
194			if m, ok := result.(map[string]any); ok {
195				if id, ok := m["task_id"].(float64); ok && id > 0 {
196					model["launched_task"] = uint64(id)
197				}
198			}
199		}
200		// Re-seed the launch form: without the base request the re-rendered form goes blank.
201		model["base_exchange"], model["base_msgid"], model["base_request"] = ui2LatestExchange(s)
202		ui2Fragment(w, r, "burpsy /ui2/ — Intruder", "intruder", ui2Exec("intruder.html", model))
203	}
