393	// ui2SequencerCapturePayload builds the /api/sequencer/capture body from the start form.
394	// Zero-value count/delay/threads are left for the API's own defaults and validation to
395	// report, so the reviewed body is exactly what the operator typed.
396	func ui2SequencerCapturePayload(r *http.Request) (map[string]any, string) {
397		count, errText := ui2ParseCount("count", r.PostFormValue("count"))
398		delay, err := ui2ParseCount("delay_ms", r.PostFormValue("delay_ms"))
399		if errText == "" {
400			errText = err
401		}
402		threads, err := ui2ParseCount("threads", r.PostFormValue("threads"))
403		if errText == "" {
404			errText = err
405		}
406		loc := map[string]any{"kind": r.PostFormValue("kind")}
407		if n := r.PostFormValue("name"); n != "" {
408			loc["name"] = n
409		}
410		if p := r.PostFormValue("pattern"); p != "" {
411			loc["pattern"] = p
412		}
413		return map[string]any{
414			"target":   r.PostFormValue("target"),
415			"protocol": r.PostFormValue("protocol"),
416			// The textarea round-trips line endings as lone LF; the head must be CRLF on the
417			// wire or many servers never answer (the repeater's ui2RestoreHeaderNewlines).
418			"request":  ui2RestoreHeaderNewlines(r.PostFormValue("request")),
419			"count":    count,
420			"delay_ms": delay,
421			"threads":  threads,
422			"location": loc,
423		}, errText
424	}
