630		}
631		sub := func(mm map[string]any, k string) map[string]any {
632			v, _ := mm[k].(map[string]any)
633			return v
634		}
635		var sb strings.Builder
636		fmt.Fprintf(&sb, "Grade: %s\n", strOf(m["grade"]))
637		if v := strOf(m["verdict"]); v != "" {
638			fmt.Fprintf(&sb, "Verdict: %s\n", v)
639		}
640		// Provenance: what the sample went through before any figure was computed.
641		// An operator reading a number must know whether the tokens were re-encoded,
642		// decoded, or padded first — a figure over transformed input read as a
643		// figure over the pasted text is a wrong conclusion with a citation.
644		if enc := strOf(m["encoding"]); enc != "" {
645			line := "Encoding: " + enc
646			if d, _ := m["encoding_detected"].(bool); d {
647				line += " (detected from the sample, not chosen by the operator)"
648			}
649			sb.WriteString(line + "\n")
650		}
651		if b, _ := m["base64_decoded"].(bool); b {
652			sb.WriteString("Base64: tokens were base64-decoded to their underlying bytes before analysis - every figure below describes the decoded bytes, not the base64 text\n")
653		}
654		if p := sub(m, "padding"); p != nil {
655			switch strOf(p["mode"]) {
656			case "start", "end":
657				fmt.Fprintf(&sb, "Padding: %v token(s) padded at %s with %s (%v byte(s) added; original token lengths %v..%v)\n",
658					p["tokens_padded"], strOf(p["mode"]), strOf(p["pad_byte_label"]), p["pad_bytes_added"], p["orig_min_len"], p["orig_max_len"])
659			default:
660				sb.WriteString("Padding: none - short tokens are excluded from the positions they do not reach rather than padded with invented characters\n")
661			}
662		}
663		if ee := sub(m, "effective_entropy"); ee != nil {
664			chosen := sub(ee, "chosen")
665			if c, _ := chosen["computed"].(bool); c {
666				line := fmt.Sprintf("Effective entropy: %v bit(s) at %v%% significance",
667					chosen["bits"], ee["significance_percent"])
668				if d, _ := ee["significance_defaulted"].(bool); d {
669					line += " (significance defaulted, not chosen)"
670				}
671				sb.WriteString(line + "\n")
672			} else {
673				// Computed false means Bits is null: printing the figure line
674				// anyway rendered "Effective entropy: <nil>" on samples too small
675				// to support an answer. Name the miss and give the engine's reason.
676				line := "Effective entropy: not computed on this sample"
677				if r := strOf(chosen["reason"]); r != "" {
678					line += " - " + r
679				}
680				sb.WriteString(line + "\n")
681			}
682		}
683		if ws, _ := m["warnings"].([]any); len(ws) > 0 {
684			sb.WriteString("Warnings:\n")
685			for _, w := range ws {
686				fmt.Fprintf(&sb, "- %s\n", strOf(w))
687			}
688		}
689		if c := sub(m, "characters"); c != nil {
690			fmt.Fprintf(&sb, "Characters: %v tokens, lengths %v..%v, alphabet %v, %.2f bits/char, %.2f bits total",
691				num(c["tokens"]), num(c["min_len"]), num(c["max_len"]), num(c["alphabet_size"]),
692				num(c["entropy_bits_per_char"]), num(c["total_entropy_bits"]))
693			if a, _ := c["assumes_positional_independence"].(bool); a {
694				sb.WriteString(" (positional independence assumed)")
695			}
696			sb.WriteByte('\n')
697		}
698		if es := sub(m, "extra_stats"); es != nil {
699			fmt.Fprintf(&sb, "Extra stats: chi-square %v, serial correlation %.4f, Monte Carlo pi %v (deviation %.4f), repeated tokens %v\n",
700				es["chi_square"], num(es["serial_correlation"]), es["monte_carlo_pi"], num(es["monte_carlo_deviation"]), es["repeated_tokens"])
701		}
702		if b := sub(m, "bits"); b != nil {
703			fmt.Fprintf(&sb, "Bits: %v supplied, bit entropy %.4f, longest run %v\n",
704				num(b["bits"]), num(b["bit_entropy"]), num(b["longest_run"]))
705		}
706		if f := sub(m, "fips"); f != nil {
707			fmt.Fprintf(&sb, "FIPS 140-2: %v of %v supplied bits tested (%v-bit blocks, %v complete) - untested bits are not failed bits\n",
708				num(f["bits_tested"]), num(f["bits_supplied"]), num(f["block_bits"]), num(f["blocks_tested"]))
709		}
710		if fp := sub(m, "fips_positions"); fp != nil {
711			if c, _ := fp["computed"].(bool); !c {
712				fmt.Fprintf(&sb, "Per-position significance: not computed - %s\n", strOf(fp["reason"]))
713			}
714		}
715		if adv := sub(m, "advanced"); adv != nil {
716			fmt.Fprintf(&sb, "Extended tests: %s (grade affected: %v)\n", strOf(adv["summary"]), adv["affects_grade"])
717			for _, t := range adv["tests"].([]any) {
718				tm, _ := t.(map[string]any)
719				if tm == nil {
720					continue
721				}
722				name := strOf(tm["name"])
723				if tested, _ := tm["tested"].(bool); !tested {
724					fmt.Fprintf(&sb, "  - %s: not testable on this sample - %s\n", name, strOf(tm["reason"]))
725				} else if passed, _ := tm["passed"].(bool); passed {
726					fmt.Fprintf(&sb, "  - %s: PASS (observed %v, threshold %v)\n", name, tm["observed"], tm["threshold"])
727				} else {
728					fmt.Fprintf(&sb, "  - %s: FAIL (observed %v, flagged %v of %v examined, threshold %v)\n",
729						name, tm["observed"], tm["flagged"], tm["examined"], tm["threshold"])
730				}
731			}
732		}
733		return sb.String()
734	}
